'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useState } from 'react'
import Button from '@mui/material/Button'
import Grid from '@mui/material/Grid'
import { useTranslations } from 'next-intl'
import { ApiError } from '@/lib/api/client'
import { useConstraints } from '@/lib/reference'
import { Modal } from '@/components/modal'
import { SelectField, TextField } from '@/components/form-fields'
import { useToast } from '@/components/toast-provider'
import { useOptions } from '../shared'
import { useSaveOrder } from './api'
import type { Order, OrderInput } from './types'

interface FormState {
  orderedOn: string
  status: string
  customerId: string
}

export function OrderFormModal({ row, onClose }: { row: Order | null; onClose: () => void }) {
  const t = useTranslations('shop')
  const tCommon = useTranslations('common')
  const field = useConstraints('shopOrder')
  const toast = useToast()
  const save = useSaveOrder()
  const customerIdOptions = useOptions('/api/shop/customers', 'id', 'email')
  const [form, setForm] = useState<FormState>({
    orderedOn: row?.orderedOn ?? '',
    status: row?.status ?? '',
    customerId: row?.customerId != null ? String(row?.customerId) : '',
  })
  const errors = save.error instanceof ApiError ? save.error.fieldErrors : {}
  const set =
    <K extends keyof FormState>(key: K) =>
    (value: FormState[K]) =>
      setForm(f => ({ ...f, [key]: value }))

  const submit = () => {
    const input: OrderInput = {
      orderedOn: form.orderedOn || null,
      status: form.status || null,
      customerId: form.customerId === '' ? null : Number(form.customerId),
    }
    save.mutate(
      { id: row?.id, input },
      {
        onSuccess: () => {
          toast.success(row ? tCommon('saved') : tCommon('created'))
          onClose()
        },
        onError: error => {
          if (!(error instanceof ApiError) || Object.keys(error.fieldErrors).length === 0) {
            toast.error(error instanceof ApiError ? error.message : tCommon('unknownError'))
          }
        },
      }
    )
  }

  return (
    <Modal
      open
      title={row ? t('order.edit') : t('order.new')}
      onClose={onClose}
      busy={save.isPending}
      onSubmit={submit}
      footer={
        <>
          <Button variant="outlined" color="inherit" onClick={onClose} disabled={save.isPending}>
            {tCommon('cancel')}
          </Button>
          <Button type="submit" variant="contained" disabled={save.isPending}>
            {save.isPending ? tCommon('saving') : tCommon('save')}
          </Button>
        </>
      }
    >
      <Grid container spacing={2}>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('order.fields.orderedOn')}
            type="date"
            value={form.orderedOn}
            onChange={set('orderedOn')}
            {...field('orderedOn')}
            error={errors.orderedOn}
          />
        </Grid>
        <Grid size={{ xs: 12, md: 6 }}>
          <TextField
            label={t('order.fields.status')}
            value={form.status}
            onChange={set('status')}
            {...field('status')}
            error={errors.status}
          />
        </Grid>
        <Grid size={{ xs: 12, md: 6 }}>
          <SelectField
            label={t('order.fields.customerId')}
            value={form.customerId}
            onChange={set('customerId')}
            required={field('customerId').required}
            error={errors.customerId}
          >
            <option value="">–</option>
            {(customerIdOptions.data ?? []).map(o => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </SelectField>
        </Grid>
      </Grid>
    </Modal>
  )
}
